head.b:skin:
/* ===== RESET BLOGGER ===== */
body#layout .hidden {display:block}
body {
  font-family: 'Segoe UI', Roboto, sans-serif;
  background: radial-gradient(circle at center, #111827 0%, #05070a 100%);
  color:#fff;
  margin:0;
  min-height:100vh;
}
/* ===== ORIGINAL NEON SLOT ===== */
:root {
  --bg-body: #05070a;
  --glass-bg: rgba(15, 23, 42, 0.8);
  --neon-blue: #00d2ff;
  --neon-pink: #ff007f;
  --neon-green: #39ff14;
  --gold: #d4af37;
  --text-main: #ffffff;
}
.app-wrapper{
  max-width:1100px;
  margin:0 auto;
  padding:20px;
}
.topbar{
  display:flex;
  justify-content:space-between;
  align-items:center;
  background:rgba(15,23,42,0.9);
  backdrop-filter:blur(12px);
  border:1px solid rgba(255,255,255,0.1);
  border-radius:16px;
  padding:12px 20px;
  margin-bottom:20px;
}
.logo{
  font-weight:900;
  letter-spacing:4px;
  background: linear-gradient(to right, #d4af37, #fff, #f9e29b);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  font-size:1.6rem;
}
.balance-box{
  background:linear-gradient(135deg,#00d2ff,#3a7bd5);
  padding:8px 16px;
  border-radius:10px;
  font-weight:800;
}
.card{
  background:var(--glass-bg);
  backdrop-filter:blur(20px);
  border-radius:20px;
  border:1px solid rgba(255,255,255,0.1);
  padding:20px;
  box-shadow:0 0 30px rgba(0,0,0,0.5);
  margin-bottom:20px;
}
h2.section-title{
  color:#64748b;
  font-size:0.85rem;
  letter-spacing:2px;
  text-transform:uppercase;
  margin:0 0 15px 0;
}
.btn{
  padding:12px 20px;
  border-radius:12px;
  border:none;
  font-weight:800;
  cursor:pointer;
  text-transform:uppercase;
  letter-spacing:1px;
  transition:0.2s;
}
.btn-primary{
  background:linear-gradient(135deg,#00d2ff,#3a7bd5);
  color:#fff;
  box-shadow:0 0 20px rgba(0,210,255,0.4);
}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 0 30px var(--neon-blue);}
.btn-secondary{
  background:rgba(255,0,127,0.1);
  border:1px solid var(--neon-pink);
  color:var(--neon-pink);
}
.btn-gold{
  background:linear-gradient(135deg,#d4af37,#f9e29b);
  color:#000;
}
.input{
  width:100%;
  padding:12px;
  border-radius:10px;
  border:1px solid rgba(255,255,255,0.15);
  background:rgba(0,0,0,0.4);
  color:#fff;
  margin-bottom:10px;
  box-sizing:border-box;
}
/* SLOT MACHINE */
.slot-machine {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-bottom: 20px;
  perspective: 1000px;
}
.slot-column {
  width: 90px;
  height: 120px;
  background: #000;
  border-radius: 15px;
  border: 2px solid var(--neon-blue);
  box-shadow: 0 0 20px rgba(0, 210, 255, 0.3), inset 0 0 10px #000;
  overflow: hidden;
  position: relative;
}
.slot-wrapper {
  position: absolute;
  width: 100%;
  top: 0;
  left: 0;
  will-change: transform;
}
.slot-number {
  height: 120px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 70px;
  font-weight: 900;
  color: var(--neon-blue);
  text-shadow: 0 0 15px var(--neon-blue);
}
@keyframes spinInfinite {0%{transform:translateY(0)}100%{transform:translateY(-1500px)}}
.spinning-infinite{animation:spinInfinite 0.3s linear infinite}
.spinning-infinite-fast{animation:spinInfinite 0.15s linear infinite}

/* TICKET STYLE - giống ảnh bạn gửi */
.ticket{
  width:100%;
  max-width:360px;
  background:#fff;
  border:3px solid #b71c1c;
  border-radius:4px;
  overflow:hidden;
  margin:10px auto;
  box-shadow:0 4px 15px rgba(0,0,0,0.4);
}
.ticket-grid{
  display:grid;
  grid-template-columns:repeat(9,1fr);
  grid-template-rows:repeat(3, 48px);
}
.ticket-cell{
  display:flex;
  align-items:center;
  justify-content:center;
  font-weight:900;
  font-size:1.3rem;
  border:1px solid #b71c1c;
  position:relative;
}
.ticket-cell.empty{
  background:#e53935;
}
.ticket-cell.filled{
  background:#fff;
  color:#000;
}
.ticket-cell.hit{
  background:#39ff14 !important;
  color:#000;
  box-shadow:inset 0 0 10px rgba(0,0,0,0.3);
  animation:pop 0.4s;
}
@keyframes pop{0%{transform:scale(1)}50%{transform:scale(1.2)}100%{transform:scale(1)}}
.ticket-footer{
  background:#fff;
  color:#d81b60;
  font-family:cursive;
  text-align:center;
  padding:4px;
  font-size:0.8rem;
  border-top:2px dashed #e53935;
}
.tickets-choice{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(280px,1fr));
  gap:15px;
}
.ticket-selectable{cursor:pointer;transition:0.2s}
.ticket-selectable:hover{transform:scale(1.03);box-shadow:0 0 20px var(--neon-blue)}
.ticket-selectable.selected{outline:3px solid var(--neon-blue);box-shadow:0 0 30px var(--neon-blue)}

.drawn-number {
  width: 38px;
  height: 38px;
  line-height: 38px;
  text-align: center;
  margin: 5px;
  font-weight: 800;
  font-size: 1rem;
  color: #fff;
  border-radius: 10px;
  background: linear-gradient(145deg, #1e293b, #0f172a);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 5px 5px 10px #05070a, -2px -2px 5px rgba(255,255,255,0.05);
  display:inline-block;
}
.countdown{
  font-size:4rem;
  font-weight:900;
  color:var(--gold);
  text-align:center;
  animation:countPulse 1s infinite;
}
@keyframes countPulse{0%{transform:scale(1)}50%{transform:scale(1.3)}100%{transform:scale(1)}}

.modal{
  position:fixed;
  inset:0;
  background:rgba(0,0,0,0.8);
  display:none;
  align-items:center;
  justify-content:center;
  z-index:9999;
}
.modal.open{display:flex}
.modal-box{
  background:#0f172a;
  border:1px solid rgba(255,255,255,0.15);
  border-radius:20px;
  padding:25px;
  width:90%;
  max-width:400px;
}
.flex{display:flex;gap:10px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}

b:includable.script:
//
// ===== CONFIG - THAY BẰNG KEY CỦA BẠN =====
const SUPABASE_URL = 'https://YOUR_PROJECT.supabase.co';
const SUPABASE_ANON_KEY = 'YOUR_ANON_KEY';
const BACKEND_URL = 'https://your-backend.onrender.com'; // Node server
const APPSCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwKymV4CKouo3JDEkHvrsQvd7Ax6KBqUiTW-rPyEYMe37tfMA0_ieGsfUhjyJqh1BeIJw/exec';

const supabase = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
let socket = null;
let currentUser = null;
let authMode = 'login';
let generatedTickets = [];
let selectedTicket = null;
let selectedTicketIndex = -1;
let currentRoomId = null;
let currentPlayers = [];

// ===== AUTH =====
async function checkUser(){
  const {data:{session}} = await supabase.auth.getSession();
  if(session){
    currentUser = session.user;
    const {data:profile} = await supabase.from('profiles').select('*').eq('id',currentUser.id).single();
    document.getElementById('userInfo').style.display='block';
    document.getElementById('usernameDisplay').innerText = profile?.username || currentUser.email;
    document.getElementById('balanceDisplay').innerText = (profile?.balance||0).toLocaleString()+' xu';
    document.getElementById('btnOpenAuth').style.display='none';
    connectSocket();
  }
}
function openAuthModal(){ document.getElementById('authModal').classList.add('open'); }
function closeAuthModal(){ document.getElementById('authModal').classList.remove('open'); }
function toggleAuthMode(){
  authMode = authMode==='login'?'register':'login';
  document.getElementById('authTitle').innerText = authMode==='login'?'Đăng nhập':'Đăng ký';
  document.getElementById('btnAuthSubmit').innerText = authMode==='login'?'Đăng nhập':'Đăng ký';
  document.getElementById('authUsernameWrap').style.display = authMode==='register'?'block':'none';
  document.getElementById('toggleAuthLink').innerText = authMode==='login'?'Chưa có tài khoản? Đăng ký':'Đã có tài khoản? Đăng nhập';
}
async function handleAuth(){
  const email = document.getElementById('authEmail').value.trim();
  const pass = document.getElementById('authPass').value;
  const username = document.getElementById('authUsername').value.trim();
  if(!email||!pass) return alert('Nhập đủ email/pass');
  if(authMode==='login'){
    const {data, error} = await supabase.auth.signInWithPassword({email,password:pass});
    if(error) return alert(error.message);
    closeAuthModal(); checkUser();
  }else{
    const {data, error} = await supabase.auth.signUp({email,password:pass});
    if(error) return alert(error.message);
    if(data.user){
      await supabase.from('profiles').upsert({id:data.user.id, email, username: username||email.split('@')[0], balance:100000});
      alert('Đăng ký thành công! Kiểm tra email xác nhận nếu cần, rồi đăng nhập.');
      toggleAuthMode();
    }
  }
}
async function logout(){
  await supabase.auth.signOut();
  location.reload();
}

// ===== OTP qua Apps Script =====
function openForgotModal(){ document.getElementById('forgotModal').classList.add('open'); }
function closeForgotModal(){ document.getElementById('forgotModal').classList.remove('open'); }
async function sendOTP(){
  const email = document.getElementById('forgotEmail').value.trim();
  if(!email) return alert('Nhập email');
  const btn = event.target; btn.innerText='Đang gửi...'; btn.disabled=true;
  try{
    const res = await fetch(BACKEND_URL+'/api/otp/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});
    const j = await res.json();
    if(j.ok){ alert('Đã gửi OTP qua mail!'); document.getElementById('otpSection').style.display='block'; }
    else alert('Lỗi gửi OTP');
  }catch(e){ 
    // fallback gọi trực tiếp Apps Script nếu backend chưa chạy
    await fetch(APPSCRIPT_URL, {method:'POST',mode:'no-cors',body:JSON.stringify({action:'sendOTP',email,otp: Math.floor(100000+Math.random()*900000)})});
    alert('Đã gửi OTP (qua Apps Script trực tiếp). Kiểm tra mail!');
    document.getElementById('otpSection').style.display='block';
  }
  btn.innerText='Gửi OTP qua Apps Script'; btn.disabled=false;
}
async function verifyOTP(){
  const email = document.getElementById('forgotEmail').value.trim();
  const otp = document.getElementById('otpCode').value.trim();
  const newPassword = document.getElementById('newPass').value;
  if(!otp||!newPassword) return alert('Nhập OTP và mật khẩu mới');
  const res = await fetch(BACKEND_URL+'/api/otp/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email, otp, newPassword})});
  const j = await res.json();
  if(j.ok){ alert('Đổi mật khẩu thành công! Đăng nhập lại.'); closeForgotModal(); }
  else alert(j.message||'OTP sai');
}

// ===== SOCKET =====
function connectSocket(){
  if(socket) return;
  socket = io(BACKEND_URL);
  socket.on('players-update', (players)=>{ currentPlayers=players; renderPlayersTickets(); });
  socket.on('countdown-start', ()=>{ doCountdown(); });
  socket.on('number-drawn', ({number, drawn})=>{ showDrawnNumber(number, drawn); });
  socket.on('game-won', ({winner, number, winAmount, fee, totalPot})=>{
    fireConfetti();
    alert(`🎉 Người thắng: ${winner.bot_name||winner.user_id} - Trúng số ${number}\nTổng pot: ${totalPot} - Phí ${fee} - Thắng nhận: ${winAmount}`);
    document.getElementById('btnStartGame').disabled=false;
  });
  socket.on('error', (msg)=> alert(msg));
}

function doCountdown(){
  const area = document.getElementById('countdownArea');
  const txt = document.getElementById('countdownText');
  area.style.display='block';
  let c=3; txt.innerText=c;
  const iv = setInterval(()=>{ c--; if(c>0){ txt.innerText=c; } else if(c===0){ txt.innerText='GO!'; } else { clearInterval(iv); area.style.display='none'; } }, 1000);
}

// ===== TICKET GENERATION (giống ảnh) =====
function generateLotoTicket(){
  // copy logic từ backend để preview offline
  const ranges=[[1,9],[10,19],[20,29],[30,39],[40,49],[50,59],[60,69],[70,79],[80,90]];
  let ticket = Array(3).fill(0).map(()=> Array(9).fill(null));
  for(let c=0;c<9;c++){
    const r=Math.floor(Math.random()*3);
    ticket[r][c]= Math.floor(Math.random()*(ranges[c][1]-ranges[c][0]+1))+ranges[c][0];
  }
  for(let r=0;r<3;r++){
    let cnt=ticket[r].filter(v=>v!==null).length;
    while(cnt<5){
      const c=Math.floor(Math.random()*9);
      if(ticket[r][c]===null){
        ticket[r][c]= Math.floor(Math.random()*(ranges[c][1]-ranges[c][0]+1))+ranges[c][0];
        cnt++;
      }
    }
  }
  // sort columns
  for(let c=0;c<9;c++){
    let vals=[]; for(let r=0;r<3;r++) if(ticket[r][c]!==null) vals.push(ticket[r][c]);
    vals.sort((a,b)=>a-b); let idx=0;
    for(let r=0;r<3;r++) if(ticket[r][c]!==null) ticket[r][c]=vals[idx++];
  }
  return ticket;
}

async function generateTicketsForSolo(){
  if(!currentUser) return openAuthModal();
  const count=6;
  // thử gọi backend, nếu fail thì gen local
  try{
    const res= await fetch(BACKEND_URL+'/api/tickets/generate?count='+count);
    const j= await res.json();
    generatedTickets=j.tickets;
  }catch(e){ generatedTickets=Array(count).fill(0).map(()=> generateLotoTicket()); }
  renderTicketChoices();
}

function renderTicketChoices(){
  document.getElementById('ticketChoiceArea').style.display='block';
  const container=document.getElementById('ticketsContainer');
  container.innerHTML='';
  generatedTickets.forEach((ticket,i)=>{
    const div=document.createElement('div');
    div.className='ticket ticket-selectable';
    div.innerHTML=renderTicketHTML(ticket);
    div.onclick=()=>{ document.querySelectorAll('.ticket-selectable').forEach(el=>el.classList.remove('selected')); div.classList.add('selected'); selectedTicket=ticket; selectedTicketIndex=i; document.getElementById('btnConfirmTicket').style.display='block'; };
    container.appendChild(div);
  });
  document.getElementById('ticketChoiceArea').scrollIntoView({behavior:'smooth'});
}

function renderTicketHTML(ticket, drawnSet){
  let html='<div class="ticket-grid">';
  for(let r=0;r<3;r++){
    for(let c=0;c<9;c++){
      const val=ticket[r][c];
      if(val===null){ html+=`<div class="ticket-cell empty"></div>`; }
      else{
        const hit = drawnSet && drawnSet.has(val) ? ' hit' : '';
        html+=`<div class="ticket-cell filled${hit}">${val}</div>`;
      }
    }
  }
  html+='</div><div class="ticket-footer">Phúc lộc đầy nhà ✦✦✦✦✦</div>';
  return html;
}

async function confirmTicket(){
  const botCount=parseInt(document.getElementById('botCount').value);
  const bet=parseInt(document.getElementById('soloBet').value);
  if(!selectedTicket) return alert('Chọn 1 vé');
  if(!currentUser) return openAuthModal();
  document.getElementById('lobby').style.display='none';
  document.getElementById('gameRoom').style.display='block';
  currentRoomId=null;
  document.getElementById('currentRoomId').innerText='SOLO';
  const fee=Math.max(5,20-(botCount-1)*2);
  document.getElementById('currentFee').innerText=fee;
  document.getElementById('currentBet').innerText=bet.toLocaleString();
  // gửi lên backend tạo phòng solo
  socket.emit('create-solo',{userId:currentUser.id, botCount, betAmount:bet, ticket:selectedTicket});
  socket.on('solo-created', ({roomId, fee})=>{
    currentRoomId=roomId;
    document.getElementById('currentRoomId').innerText=roomId;
    document.getElementById('currentFee').innerText=fee;
  });
}

// ===== ROOM MODE =====
async function createRoom(){
  if(!currentUser) return openAuthModal();
  const name=document.getElementById('roomName').value||'Phòng Loto';
  const password=document.getElementById('roomPass').value;
  const bet=parseInt(document.getElementById('roomBet').value)||20000;
  const res= await fetch(BACKEND_URL+'/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hostId:currentUser.id, name, password, betAmount:bet, maxPlayers:5})});
  const data= await res.json();
  if(data.id){
    currentRoomId=data.id;
    document.getElementById('lobby').style.display='none';
    document.getElementById('gameRoom').style.display='block';
    document.getElementById('currentRoomId').innerText=currentRoomId;
    document.getElementById('currentFee').innerText='20';
    document.getElementById('currentBet').innerText=bet.toLocaleString();
    socket.emit('join-room',{roomId:currentRoomId, userId:currentUser.id, password});
  }else alert('Lỗi tạo phòng');
}
function joinRoom(){
  const roomId=document.getElementById('joinRoomId').value.trim().toUpperCase();
  const password=document.getElementById('joinRoomPass').value;
  if(!roomId) return alert('Nhập ID phòng');
  if(!currentUser) return openAuthModal();
  currentRoomId=roomId;
  document.getElementById('lobby').style.display='none';
  document.getElementById('gameRoom').style.display='block';
  document.getElementById('currentRoomId').innerText=roomId;
  socket.emit('join-room',{roomId, userId:currentUser.id, password});
}

function renderPlayersTickets(){
  const container=document.getElementById('playersTickets');
  container.innerHTML='';
  const drawnSet = new Set(Array.from(document.querySelectorAll('#history-list .drawn-number')).map(el=>parseInt(el.innerText)));
  currentPlayers.forEach(p=>{
    const div=document.createElement('div');
    div.className='ticket';
    div.innerHTML=`<div style='padding:5px;background:#0f172a;color:#fff;font-size:0.8rem;text-align:center'>${p.is_bot? '🤖 '+p.bot_name : '👤 '+(p.user_id===currentUser?.id?'Bạn':p.user_id?.slice(0,6))} ${p.is_bot?'':''}</div>`+renderTicketHTML(p.ticket, drawnSet);
    container.appendChild(div);
  });
}

function showDrawnNumber(num, drawnAll){
  // slot animation giống bản gốc
  const tens=Math.floor(num/10), ones=num%10;
  const wT=document.getElementById('wrapper-tens'), wO=document.getElementById('wrapper-ones');
  wT.innerHTML=`<div class="slot-number">${tens}</div>`;
  wO.innerHTML=`<div class="slot-number">${ones}</div>`;
  wT.style.transform='translateY(0)'; wO.style.transform='translateY(0)';
  setTimeout(()=>{ wT.innerHTML=`<div class="slot-number">${tens}</div>`; },200);
  const span=document.createElement('div');
  span.className='drawn-number';
  span.innerText=num;
  document.getElementById('history-list').prepend(span);
  document.getElementById('drawnCount').innerText=drawnAll.length;
  renderPlayersTickets();
}

function startGame(){
  if(!currentRoomId) return alert('Chưa vào phòng');
  document.getElementById('btnStartGame').disabled=true;
  socket.emit('start-game',{roomId:currentRoomId});
}
function leaveRoom(){
  if(socket && currentRoomId) socket.emit('leave-room',currentRoomId);
  document.getElementById('gameRoom').style.display='none';
  document.getElementById('lobby').style.display='block';
  document.getElementById('history-list').innerHTML='';
  document.getElementById('drawnCount').innerText='0';
  currentRoomId=null;
}

function fireConfetti(){ confetti({particleCount:150,spread:70,origin:{y:0.6}}); }

// init
checkUser();
document.getElementById('botCount').addEventListener('input', (e)=>{
  document.getElementById('botCountLabel').innerText=e.target.value;
  const fee=Math.max(5,20-(e.target.value-1)*2);
  document.getElementById('feeInfo').innerText=`Phí sàn: ${fee}% - Càng nhiều bot phí càng thấp`;
});
//
